import { create, type StoreApi, type UseBoundStore } from 'zustand';
import { persist, subscribeWithSelector, type PersistStorage, type StorageValue } from 'zustand/middleware';
import { immer } from 'zustand/middleware/immer';
import { cancelPending, debouncedSetItem } from './debouncedPersist';
import { safeParseJSON } from './utils/safeParseJSON';

type WritableState = Record<string, any>;
type BoundStore<S extends WritableState> = UseBoundStore<StoreApi<S>>;

export interface CreateOsStoreOptions<S extends WritableState> {
  persistName?: string;
  registerToServiceRegistry?: boolean;
  /** Register this store as a Provider (snapshot under os.providers) */
  registerToProviderRegistry?: boolean;
  useImmer?: boolean;
  validate?: (raw: unknown, defaults: S) => S;
}

// ---------------------------------------------------------------------------
// Internal store registry (replaces the former ServiceRegistry.ts singleton)
// ---------------------------------------------------------------------------

interface RegisteredStore {
  name: string;
  getState: () => any;
  reset: () => void;
}

const _registry = new Map<string, RegisteredStore>();
const _providerRegistry = new Map<string, RegisteredStore>();
const _providerStoreRefs = new Map<string, BoundStore<any>>();

export function resetAllOsStores(): void {
  for (const entry of _registry.values()) {
    try {
      entry.reset();
    } catch (err) {
      console.error(`[OsStoreRegistry] reset failed: ${entry.name}`, err);
    }
  }
  for (const entry of _providerRegistry.values()) {
    try {
      entry.reset();
    } catch (err) {
      console.error(`[OsStoreRegistry] provider reset failed: ${entry.name}`, err);
    }
  }
}

export function snapshotOsStores(): Record<string, any> {
  const out: Record<string, any> = {};
  for (const [name, entry] of _registry) {
    try {
      out[name] = entry.getState();
    } catch (err) {
      console.error(`[OsStoreRegistry] snapshot failed: ${name}`, err);
    }
  }
  return out;
}

export function snapshotProviders(): Record<string, any> {
  const out: Record<string, any> = {};
  for (const [name, entry] of _providerRegistry) {
    try {
      out[name] = entry.getState();
    } catch (err) {
      console.error(`[OsStoreRegistry] provider snapshot failed: ${name}`, err);
    }
  }
  return out;
}

export function patchProviders(patch: Record<string, any>, deep: boolean): string[] {
  const patched: string[] = [];
  const deepMerge = (target: any, source: any): any => {
    if (source === undefined) return target;
    if (source === null) return null;
    if (typeof source !== 'object' || Array.isArray(source)) return source;
    if (typeof target !== 'object' || target === null || Array.isArray(target)) return source;
    const result = { ...target };
    for (const key of Object.keys(source)) {
      result[key] = deepMerge(target[key], source[key]);
    }
    return result;
  };

  for (const [providerName, providerPatch] of Object.entries(patch)) {
    if (providerPatch === undefined || providerPatch === null) continue;
    const store = _providerStoreRefs.get(providerName);
    if (!store) {
      console.warn(`[patchProviders] unknown provider '${providerName}', registered:`, [..._providerStoreRefs.keys()]);
      continue;
    }
    if (deep) {
      const current = store.getState();
      const currentData: Record<string, any> = {};
      for (const [k, v] of Object.entries(current as Record<string, any>)) {
        if (typeof v !== 'function') currentData[k] = v;
      }
      const merged = deepMerge(currentData, providerPatch);
      (store.setState as any)(merged, true);
    } else {
      (store.setState as any)(providerPatch, true);
    }
    patched.push(providerName);
  }
  return patched;
}

/** @internal — exposed only for unit tests */
export const _testOnlyRegistry = {
  register(entry: RegisteredStore): void {
    if (!entry?.name) return;
    _registry.set(entry.name, entry);
  },
  get(name: string): RegisteredStore | undefined {
    return _registry.get(name);
  },
  size(): number {
    return _registry.size;
  },
};

// ---------------------------------------------------------------------------
// Store factory helpers
// ---------------------------------------------------------------------------

function cloneState<S>(value: S): S {
  if (typeof structuredClone === 'function') {
    return structuredClone(value);
  }
  return JSON.parse(JSON.stringify(value)) as S;
}

function createStorage<S extends WritableState>(
  validate?: (raw: unknown, defaults: S) => S,
  defaults?: S,
): PersistStorage<S> {
  return {
    getItem(key: string): StorageValue<S> | null {
      const parsed = safeParseJSON<any>(localStorage.getItem(key));
      if (parsed == null) return null;

      if (!parsed || typeof parsed !== 'object' || !('state' in parsed)) return null;

      const state = validate && defaults ? validate(parsed.state, defaults) : parsed.state;
      return {
        state,
        version: typeof parsed.version === 'number' ? parsed.version : 0,
      };
    },
    setItem(key: string, value: StorageValue<S>) {
      debouncedSetItem(key, JSON.stringify(value));
    },
    removeItem(key: string) {
      cancelPending(key);
      localStorage.removeItem(key);
    },
  };
}

function registerStore<S extends WritableState>(
  name: string,
  store: BoundStore<S>,
  getDefaultState: () => S,
  registry: Map<string, RegisteredStore> = _registry,
) {
  registry.set(name, {
    name,
    getState: store.getState,
    reset: () => store.setState(getDefaultState(), true),
  });
}

// ---------------------------------------------------------------------------
// Public factory functions
// ---------------------------------------------------------------------------

export function createOsStore<S extends WritableState>(
  name: string,
  defaultState: S,
  options?: CreateOsStoreOptions<S>,
): BoundStore<S> {
  const useImmer = options?.useImmer ?? true;
  const registerService = options?.registerToServiceRegistry ?? true;
  const registerProvider = options?.registerToProviderRegistry ?? false;
  const getDefaultState = () => cloneState(defaultState);
  const storage = createStorage(options?.validate, defaultState);
  const initializer = () => getDefaultState();

  const store = (
    useImmer
      ? create<S>()(subscribeWithSelector(persist(immer(initializer as any), {
          name: options?.persistName ?? name,
          storage,
        })))
      : create<S>()(subscribeWithSelector(persist(initializer, {
          name: options?.persistName ?? name,
          storage,
        })))
  ) as BoundStore<S>;

  if (registerProvider) {
    const providerKey = name.startsWith('provider.') ? name.slice('provider.'.length) : name;
    registerStore(providerKey, store, getDefaultState, _providerRegistry);
    _providerStoreRefs.set(providerKey, store);
  } else if (registerService) {
    registerStore(name, store, getDefaultState);
  }

  return store;
}

export function createVolatileOsStore<S extends WritableState>(
  name: string,
  defaultState: S,
  options?: Pick<CreateOsStoreOptions<S>, 'registerToServiceRegistry' | 'useImmer'>,
): BoundStore<S> {
  const useImmer = options?.useImmer ?? true;
  const register = options?.registerToServiceRegistry ?? true;
  const getDefaultState = () => cloneState(defaultState);
  const initializer = () => getDefaultState();

  const store = (
    useImmer
      ? create<S>()(subscribeWithSelector(immer(initializer as any)))
      : create<S>()(subscribeWithSelector(initializer))
  ) as BoundStore<S>;

  if (register) {
    registerStore(name, store, getDefaultState);
  }

  return store;
}

import ContentProvider from './ContentProvider';
import type { ContentUri, ContentValues, Cursor } from './types/content';
import BroadcastBus, { ACTION_PROVIDER_CHANGED } from './BroadcastBus';
import PackageManagerService from './PackageManagerService';

type ContentObserver = (uri: ContentUri) => void;

type ParsedContentUri = {
  uri: ContentUri;
  authority: string;
  path: string;
  query: URLSearchParams;
};

const providers = new Map<string, ContentProvider>();

function parseUri(uri: ContentUri): ParsedContentUri {
  const raw = String(uri ?? '').trim();
  if (!raw) throw new Error('[ContentResolver] URI is required');
  if (!raw.startsWith('content:')) {
    const scheme = raw.match(/^([^:]+):/)?.[1] ?? '';
    throw new Error(`[ContentResolver] Unsupported scheme: ${scheme ? `${scheme}:` : '(none)'}; uri=${JSON.stringify(raw)}`);
  }

  const match = raw.match(/^content:\/\/([^/?#]+)([^?#]*)?(?:\?([^#]*))?(?:#.*)?$/);
  const authority = String(match?.[1] ?? '').trim();
  if (!authority) throw new Error(`[ContentResolver] Missing authority; uri=${JSON.stringify(raw)}`);
  const path = match?.[2] || '/';
  return { uri: raw, authority, path, query: new URLSearchParams(match?.[3] ?? '') };
}

function getProviderOrThrow(uri: ContentUri): { provider: ContentProvider; parsed: ParsedContentUri } {
  const parsed = parseUri(uri);
  const provider = providers.get(parsed.authority);
  if (!provider) {
    throw new Error(`[ContentResolver] No provider registered for authority="${parsed.authority}"`);
  }
  return { provider, parsed };
}

function getActiveCallerPermissions(): string[] | null {
  try {
    const os = window.__OS__;
    const state = typeof os?.getState === 'function' ? os.getState() : os?.state;
    const appId = String(state?.activeAppId ?? '').trim();
    if (!appId) return null;
    const manifest = PackageManagerService.getPackageInfo(appId);
    return manifest?.permissions ?? [];
  } catch {
    return null;
  }
}

function warnPermissionIfNeeded(provider: ContentProvider, required: string | undefined, op: string, uri: ContentUri): void {
  if (!required) return;
  const granted = getActiveCallerPermissions();
  if (!granted) return;
  if (granted.includes(required)) return;
  console.warn(
    `[ContentResolver] permission warn-only: missing "${required}" for ${op} ${uri}`,
  );
}

export const ContentResolver = {
  parseUri,

  registerProvider(authority: string, provider: ContentProvider): void {
    const key = String(authority ?? '').trim();
    if (!key) throw new Error('[ContentResolver] authority is required');
    if (!provider) throw new Error('[ContentResolver] provider is required');
    providers.set(key, provider);
  },

  query<T = any>(uri: ContentUri, projection?: string[]): Cursor<T> {
    const { provider } = getProviderOrThrow(uri);
    warnPermissionIfNeeded(provider, provider.readPermission, 'query', uri);
    return provider.query(uri, projection) as Cursor<T>;
  },

  insert(uri: ContentUri, values: ContentValues): ContentUri {
    const { provider } = getProviderOrThrow(uri);
    warnPermissionIfNeeded(provider, provider.writePermission, 'insert', uri);
    const result = provider.insert(uri, values);
    ContentResolver.notifyChange(result || uri);
    return result;
  },

  update(uri: ContentUri, values: ContentValues, where?: string): number {
    const { provider } = getProviderOrThrow(uri);
    warnPermissionIfNeeded(provider, provider.writePermission, 'update', uri);
    const changed = provider.update(uri, values, where);
    if (changed > 0) ContentResolver.notifyChange(uri);
    return changed;
  },

  delete(uri: ContentUri, where?: string): number {
    const { provider } = getProviderOrThrow(uri);
    warnPermissionIfNeeded(provider, provider.writePermission, 'delete', uri);
    const changed = provider.delete(uri, where);
    if (changed > 0) ContentResolver.notifyChange(uri);
    return changed;
  },

  notifyChange(uri: ContentUri): void {
    const parsed = parseUri(uri);
    BroadcastBus.sendBroadcast({
      action: ACTION_PROVIDER_CHANGED,
      data: { uri: parsed.uri },
      extras: { uri: parsed.uri },
    });
  },

  registerContentObserver(uri: ContentUri, cb: ContentObserver): () => void {
    const target = parseUri(uri);
    return BroadcastBus.registerReceiver(ACTION_PROVIDER_CHANGED, (intent) => {
      const changedUri = String(intent?.extras?.uri ?? intent?.data?.uri ?? '').trim();
      if (!changedUri) return;
      let parsed: ParsedContentUri;
      try {
        parsed = parseUri(changedUri);
      } catch {
        return;
      }
      if (parsed.authority !== target.authority) return;
      if (!parsed.path.startsWith(target.path)) return;
      cb(changedUri);
    });
  },
};

// App-owned provider modules (`apps/<app>/providers/*.ts`,
// `system/<app>/providers/*.ts`) are eagerly loaded from
// `os/providers/appProvidersBootstrap.ts`, NOT from here. The glob lives
// downstream so that ContentResolver is fully initialized by the time those
// modules run their top-level `ContentResolver.registerProvider(...)` calls
// (Vite hoists eager-glob imports above any `const ContentResolver = {...}`
// declaration, producing a TDZ if the glob fires before the const binds).

export default ContentResolver;
